using System.Collections;
using LittleLeo;
using NaughtyAttributes;
using Spine.Unity;
using UnityEngine;
using UnityEngine.AddressableAssets;

namespace Astrea;

[CreateAssetMenu(fileName = "AnimationData", menuName = "Data/Animation/AnimationData")]
public class AnimationData : ScriptableObject
{
	private static readonly AGLog<AnimationData> Log = new AGLog<AnimationData>();

	[SerializeField]
	[Tooltip("AssetRefFixer will fill this")]
	public AssetReferenceT<SkeletonDataAsset> SkeletonDataAssetRef;

	public AnimationState[] animationState;

	[SerializeField]
	private bool enableCustomAnimationData;

	[SerializeField]
	[ShowIf("enableCustomAnimationData")]
	private CustomAnimationData customAnimationData;

	[SerializeField]
	private bool enableCustomStartingAnimation;

	[Header("Corrupted Animal Only")]
	[Header("Corrupted Animal Purified")]
	public bool corruptedAnimal;

	[ShowIf("corruptedAnimal")]
	public AnimalPurifiedAnimation AnimalPurifiedAnimation;

	[SerializeField]
	[ShowIf("corruptedAnimal")]
	private bool enableAfterVanishAnimationLogic;

	[SerializeField]
	[ShowIf("corruptedAnimal")]
	private bool enableCustomBeingPurifiedAnimationCoroutine;

	[Header("OverCorruption")]
	[SerializeField]
	[ShowIf("showCustomOverCorruptionAnimation")]
	private bool enableCustomOverCorruptionAnimation;

	[SerializeField]
	[ShowIf("enableCustomOverCorruptionAnimation")]
	private AnimationType overCorruptionAnimationType;

	[SerializeField]
	[ShowIf("showCustomOverCorruptionAnimationComplex")]
	private bool enableCustomOverCorruptionAnimationComplex;

	[SerializeField]
	private bool dontReturnToPreviousAnimationAfterOverCorruptAnimation;

	[Header("Attack")]
	[SerializeField]
	[ShowIf("corruptedAnimal")]
	private bool enableCustomAttackAnimationLogic;

	[SerializeField]
	[ShowIf("corruptedAnimal")]
	private bool useCustomAttackAnimationLogicOnOverCorruptionAttack;

	[SerializeField]
	private bool enableCustomAttackAnimationChangeType;

	[SerializeField]
	[ShowIf("enableCustomAttackAnimationChangeType")]
	private AnimationChangeType customAttackAnimationChangeType;

	[Header("Astrea First Phase")]
	[SerializeField]
	private bool astreaFirstPhase;

	[SerializeField]
	private bool collapsedAstrea;

	[Header("Astrea Second Phase Defeat")]
	[SerializeField]
	private bool astreaSecondPhase;

	private bool modded;

	public SkeletonDataAsset SkeletonDataAsset
	{
		get
		{
			Log.Debug($"AnimationData:{this} will load SkeletonDataAsset assetGuid:{SkeletonDataAssetRef.AssetGUID}", this);
			return AGSingletonMonoBehaviour<AddressablesAssetReferenceManager>.Instance.LoadFromRef(SkeletonDataAssetRef);
		}
		set
		{
		}
	}

	public bool EnableCustomStartingAnimation => enableCustomStartingAnimation;

	public bool EnableAfterVanishAnimationLogic => enableAfterVanishAnimationLogic;

	public bool EnableCustomBeingPurifiedAnimationCoroutine => enableCustomBeingPurifiedAnimationCoroutine;

	public bool EnableCustomOverCorruptionAnimation => enableCustomOverCorruptionAnimation;

	private bool showCustomOverCorruptionAnimation
	{
		get
		{
			if (corruptedAnimal)
			{
				return !enableCustomOverCorruptionAnimationComplex;
			}
			return false;
		}
	}

	public AnimationType OverCorruptionAnimationType => overCorruptionAnimationType;

	private bool showCustomOverCorruptionAnimationComplex
	{
		get
		{
			if (corruptedAnimal)
			{
				return !enableCustomOverCorruptionAnimation;
			}
			return false;
		}
	}

	public bool EnableCustomOverCorruptionAnimationComplex => enableCustomOverCorruptionAnimationComplex;

	public bool DontReturnToPreviousAnimationAfterOverCorruptAnimation => dontReturnToPreviousAnimationAfterOverCorruptAnimation;

	public bool EnableCustomAttackAnimationLogic => enableCustomAttackAnimationLogic;

	public bool UseCustomAttackAnimationLogicOnOverCorruptionAttack => useCustomAttackAnimationLogicOnOverCorruptionAttack;

	public bool EnableCustomAttackAnimationChangeType => enableCustomAttackAnimationChangeType;

	public AnimationChangeType CustomAttackAnimationChangeType => customAttackAnimationChangeType;

	public bool AstreaFirstPhase => astreaFirstPhase;

	public bool CollapsedAstrea => collapsedAstrea;

	public bool AstreaSecondPhase => astreaSecondPhase;

	public bool Modded => modded;

	public string GetAnimationByType(AnimationType animationType)
	{
		for (int i = 0; i < this.animationState.Length; i++)
		{
			AnimationState animationState = this.animationState[i];
			if (animationState.GetAnimationType() == animationType)
			{
				return animationState.GetAnimationName();
			}
		}
		return string.Empty;
	}

	public bool HasAnimation(AnimationType animationType)
	{
		for (int i = 0; i < animationState.Length; i++)
		{
			if (animationState[i].GetAnimationType() == animationType)
			{
				return true;
			}
		}
		return false;
	}

	public float GetAnimationDuration(AnimationType animationType)
	{
		for (int i = 0; i < this.animationState.Length; i++)
		{
			AnimationState animationState = this.animationState[i];
			if (animationState.GetAnimationType() == animationType)
			{
				return SkeletonDataAsset.GetSkeletonData(quiet: false).FindAnimation(animationState.GetAnimationName()).Duration;
			}
		}
		return 0f;
	}

	public void OnReceiveCorruption(SpriteControl spriteControl, CorruptionStats corruptionStats)
	{
		if (enableCustomAnimationData)
		{
			customAnimationData.OnReceiveCorruption(spriteControl, corruptionStats, this);
		}
	}

	public bool OnReceivePurify(SpriteControl spriteControl, CorruptionStats corruptionStats)
	{
		if (enableCustomAnimationData)
		{
			return customAnimationData.OnReceivePurify(spriteControl, corruptionStats, this);
		}
		return false;
	}

	public void OnActivateDice(GameObject source)
	{
		if (enableCustomAnimationData)
		{
			customAnimationData.OnActivateDice(source);
		}
	}

	public AnimationType GetCustomAttackAnimationType(SpriteControl spriteControl, EnemySFXData enemySFXData)
	{
		if (enableCustomAnimationData)
		{
			return customAnimationData.GetCustomAttackAnimationType(spriteControl, enemySFXData);
		}
		return AnimationType.Null;
	}

	public AnimationType GetCustomOvercorruptAnimationType(SpriteControl spriteControl, EnemySFXData enemySFXData)
	{
		if (enableCustomAnimationData)
		{
			return customAnimationData.GetCustomOvercorruptAnimationType(spriteControl, enemySFXData);
		}
		return AnimationType.Null;
	}

	public void AfterVanishAnimationLogic(SpriteControl spriteControl)
	{
		if (enableCustomAnimationData)
		{
			customAnimationData.AfterVanishAnimationLogic(spriteControl);
		}
	}

	public IEnumerator CustomBeingPurifiedAnimationCoroutine(SpriteControl spriteControl)
	{
		yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(customAnimationData.CustomBeingPurifiedAnimationCoroutine(spriteControl));
	}

	public string GetCustomStartingAnimationName(GameObject animationOwner)
	{
		if (enableCustomAnimationData)
		{
			return GetAnimationByType(customAnimationData.GetCustomStartingAnimationType(animationOwner));
		}
		return "";
	}

	public Sprite GetModdedSpriteByType(AnimationType animationType)
	{
		for (int i = 0; i < this.animationState.Length; i++)
		{
			AnimationState animationState = this.animationState[i];
			if (animationState.GetAnimationType() == animationType)
			{
				return animationState.ModdedSprite;
			}
		}
		return null;
	}

	public void SetupModded(Sprite idleSprite, Sprite brokenSprite)
	{
		modded = true;
		animationState = new AnimationState[2];
		animationState[0] = new AnimationState(AnimationType.Idle, idleSprite);
		animationState[1] = new AnimationState(AnimationType.Die, brokenSprite);
	}
}
